create extension if not exists pgcrypto;
create type evidence_relationship as enum ('supports','contradicts','neutral');

create table companies (company_id uuid primary key default gen_random_uuid(), companies_house_number text unique, lei text, ticker text, legal_name text not null, display_name text not null, aliases text[] not null default '{}', sector text, subsector text, sic_codes text[] not null default '{}', geography text, website text, revenue_band text, employee_band text, active_status boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table sources (source_id uuid primary key default gen_random_uuid(), source_type text not null, source_name text not null, domain text, reliability_prior numeric(5,4) check(reliability_prior between 0 and 1), configuration jsonb not null default '{}', created_at timestamptz not null default now());
create table documents (document_id uuid primary key default gen_random_uuid(), company_id uuid references companies, source_id uuid not null references sources, source_url text not null, source_type text not null, title text not null, document_type text, period_start date, period_end date, published_at timestamptz not null, available_at timestamptz not null, retrieved_at timestamptz not null, content_hash text not null, mime_type text not null, raw_storage_path text, parsed_storage_path text, parser_version text not null, unique(source_id, content_hash));
create index documents_cutoff_idx on documents(company_id, available_at);
create table facts (fact_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, document_id uuid not null references documents, metric text not null, value_numeric numeric, value_text text, unit text, period_start date, period_end date, source_location text not null, extraction_method text not null, extraction_confidence numeric(5,4) check(extraction_confidence between 0 and 1), extractor_version text not null, created_at timestamptz not null default now(), check(value_numeric is not null or value_text is not null));
create index facts_company_metric_idx on facts(company_id, metric, period_end);
create table evidence_clusters (cluster_id uuid primary key default gen_random_uuid(), canonical_event_description text not null, earliest_available_at timestamptz not null, created_at timestamptz not null default now());
create table evidence_cluster_members (cluster_id uuid references evidence_clusters on delete cascade, fact_id uuid references facts on delete cascade, relationship text not null, similarity_score numeric(5,4), primary key(cluster_id,fact_id));
create table signals (signal_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, signal_type text not null, signal_family text not null, event_date date not null, direction smallint not null check(direction between -1 and 1), magnitude numeric, normalised_strength numeric(5,4) not null check(normalised_strength between 0 and 1), materiality numeric(5,4) not null check(materiality between 0 and 1), source_reliability numeric(5,4) not null check(source_reliability between 0 and 1), recency_weight numeric(5,4) not null check(recency_weight between 0 and 1), independence_weight numeric(5,4) not null check(independence_weight between 0 and 1), confidence numeric(5,4) not null check(confidence between 0 and 1), extraction_version text not null, created_at timestamptz not null default now());
create table operational_conditions (operational_condition_id uuid primary key default gen_random_uuid(), code text unique not null, description text not null, configuration jsonb not null default '{}');
create table model_versions (model_version text primary key, ontology_version text not null, weighting_version text not null, extractor_version text not null, benchmark_version text not null, created_at timestamptz not null default now(), release_notes text);
create table hypotheses (hypothesis_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, operational_condition_id uuid not null references operational_conditions, as_of_date date not null, probability numeric(5,4) not null check(probability between 0 and 1), confidence numeric(5,4) not null check(confidence between 0 and 1), prior_probability numeric(5,4) not null, model_version text not null references model_versions, explanation text, created_at timestamptz not null default now(), unique(company_id,operational_condition_id,as_of_date,model_version));
create table hypothesis_evidence (hypothesis_id uuid references hypotheses on delete cascade, signal_id uuid references signals, relationship evidence_relationship not null, contribution numeric not null, explanation text, primary key(hypothesis_id,signal_id));
create table scores (score_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, score_type text not null, score numeric not null, confidence numeric(5,4) not null, as_of_date date not null, model_version text not null references model_versions, components jsonb not null, created_at timestamptz not null default now(), unique(company_id,score_type,as_of_date,model_version));
create table predictions (prediction_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, outcome_type text not null, prediction_date date not null, horizon_months integer not null, probability numeric(5,4) not null, confidence numeric(5,4) not null, model_version text not null references model_versions, rationale jsonb not null, created_at timestamptz not null default now());
create table outcomes (outcome_id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, outcome_type text not null, event_date date not null, magnitude numeric, verification_source text not null, verified_at timestamptz not null);
create table assumptions (assumption_id uuid primary key default gen_random_uuid(), description text not null, rationale text not null, importance text not null, test_method text not null, status text not null, evidence text, result text, created_at timestamptz not null default now(), resolved_at timestamptz);
create table cost_log (cost_log_id uuid primary key default gen_random_uuid(), provider text not null, model text not null, operation text not null, document_id uuid references documents, input_tokens integer not null default 0, output_tokens integer not null default 0, estimated_cost numeric(12,6) not null default 0, run_id uuid not null, timestamp timestamptz not null default now());
create index cost_log_daily_idx on cost_log(timestamp,provider);
create table peer_cohort_memberships (peer_cohort_id uuid not null, company_id uuid references companies, benchmark_version text not null, criteria jsonb not null, primary key(peer_cohort_id,company_id));
create table benchmarks (benchmark_id uuid primary key default gen_random_uuid(), peer_cohort_id uuid not null, company_id uuid not null references companies, metric text not null, percentile numeric(5,2), benchmark_date date not null, benchmark_version text not null);
create table experiment_results (experiment_result_id uuid primary key default gen_random_uuid(), experiment_name text not null, model_version text not null, prediction_date date not null, configuration jsonb not null, metrics jsonb not null, created_at timestamptz not null default now());
